public class CSVParser_iterator_TriageGen0Test {

    @Test
    public void testIteratorNormalFlow() throws IOException {
        String csvContent = "a,b\n1,2\n3,4";
        try (CSVParser parser = CSVParser.parse(csvContent, CSVFormat.DEFAULT)) {
            Iterator<CSVRecord> iterator = parser.iterator();

            assertTrue(iterator.hasNext());
            CSVRecord first = iterator.next();
            assertEquals("a", first.get(0));
            assertEquals("b", first.get(1));

            assertTrue(iterator.hasNext());
            CSVRecord second = iterator.next();
            assertEquals("1", second.get(0));
            assertEquals("2", second.get(1));

            assertTrue(iterator.hasNext());
            CSVRecord third = iterator.next();
            assertEquals("3", third.get(0));
            assertEquals("4", third.get(1));

            assertFalse(iterator.hasNext());
            assertFalse(iterator.hasNext()); // Test multiple hasNext calls
        }
    }

    @Test
    public void testIteratorEmptyContent() throws IOException {
        String csvContent = "";
        try (CSVParser parser = CSVParser.parse(csvContent, CSVFormat.DEFAULT)) {
            Iterator<CSVRecord> iterator = parser.iterator();
            assertFalse(iterator.hasNext());
            assertFalse(iterator.hasNext());
            try {
                iterator.next();
                fail("Should have thrown NoSuchElementException");
            } catch (NoSuchElementException e) {
                assertEquals("No more CSV records available", e.getMessage());
            }
        }
    }

    @Test
    public void testIteratorNextWithoutHasNext() throws IOException {
        String csvContent = "val1";
        try (CSVParser parser = CSVParser.parse(csvContent, CSVFormat.DEFAULT)) {
            Iterator<CSVRecord> iterator = parser.iterator();
            // Calling next() directly without calling hasNext() first
            CSVRecord record = iterator.next();
            assertEquals("val1", record.get(0));
            assertFalse(iterator.hasNext());
        }
    }

    @Test(expected = NoSuchElementException.class)
    public void testIteratorNextEmptyWithoutHasNext() throws IOException {
        String csvContent = "";
        try (CSVParser parser = CSVParser.parse(csvContent, CSVFormat.DEFAULT)) {
            Iterator<CSVRecord> iterator = parser.iterator();
            iterator.next();
        }
    }

    @Test
    public void testIteratorAfterParserClosed() throws IOException {
        String csvContent = "val1";
        CSVParser parser;
        try {
            parser = CSVParser.parse(csvContent, CSVFormat.DEFAULT);
        } catch (Exception e) {
            fail("Setup failed");
            return;
        }

        Iterator<CSVRecord> iterator = parser.iterator();
        parser.close();

        assertFalse("hasNext should return false if parser is closed", iterator.hasNext());
        try {
            iterator.next();
            fail("next() should throw NoSuchElementException if parser is closed");
        } catch (NoSuchElementException e) {
            assertEquals("CSVParser has been closed", e.getMessage());
        }
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testIteratorRemoveUnsupported() throws IOException {
        String csvContent = "val1";
        try (CSVParser parser = CSVParser.parse(csvContent, CSVFormat.DEFAULT)) {
            Iterator<CSVRecord> iterator = parser.iterator();
            iterator.remove();
        }
    }

    @Test
    public void testIteratorIOException() throws IOException {
        // Create a reader that throws IOException on read
        Reader throwingReader = new Reader() {
            @Override
            public int read(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("Simulated IO Error");
            }

            @Override
            public void close() throws IOException {}
        };

        try (CSVParser parser = new CSVParser(throwingReader, CSVFormat.DEFAULT)) {
            Iterator<CSVRecord> iterator = parser.iterator();
            try {
                iterator.hasNext();
                fail("Should have thrown IllegalStateException due to IOException");
            } catch (IllegalStateException e) {
                assertTrue(e.getMessage().contains("IOException"));
                assertTrue(e.getMessage().contains("reading next record"));
                assertTrue(e.getCause() instanceof IOException);
            }
        }
    }
}
